[[nodiscard]] auto BuildRb82Radionuclide() -> GGEMSRadionuclideDefinition {
  std::vector<GGEMSRadionuclideEmission> emissions;
  emissions.reserve(17U);

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_725_2_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_725_2_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_725_2_keV_bin_width_micro_eV,
      },
      k_beta_plus_725_2_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_819_3_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_819_3_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_819_3_keV_bin_width_micro_eV,
      },
      k_beta_plus_819_3_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_824_7_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_824_7_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_824_7_keV_bin_width_micro_eV,
      },
      k_beta_plus_824_7_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_872_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_872_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_872_keV_bin_width_micro_eV,
      },
      k_beta_plus_872_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_901_3_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_901_3_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_901_3_keV_bin_width_micro_eV,
      },
      k_beta_plus_901_3_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_930_9_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_930_9_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_930_9_keV_bin_width_micro_eV,
      },
      k_beta_plus_930_9_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_1209_3_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_1209_3_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_1209_3_keV_bin_width_micro_eV,
      },
      k_beta_plus_1209_3_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_1424_2_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_1424_2_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_1424_2_keV_bin_width_micro_eV,
      },
      k_beta_plus_1424_2_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_1560_4_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_1560_4_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_1560_4_keV_bin_width_micro_eV,
      },
      k_beta_plus_1560_4_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_1893_4_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_1893_4_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_1893_4_keV_bin_width_micro_eV,
      },
      k_beta_plus_1893_4_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_1906_1_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_1906_1_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_1906_1_keV_bin_width_micro_eV,
      },
      k_beta_plus_1906_1_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_2604_5_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_2604_5_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_2604_5_keV_bin_width_micro_eV,
      },
      k_beta_plus_2604_5_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Positron, k_beta_plus_3381_keV_yield,
    detail::BuildTabulatedSpectrum(
      {
        .lower_edge_micro_eV = k_beta_plus_3381_keV_lower_edge_micro_eV,
        .bin_width_micro_eV = k_beta_plus_3381_keV_bin_width_micro_eV,
      },
      k_beta_plus_3381_keV_weights));

  emissions.emplace_back(
    particles::GGEMSParticleType::Gamma, k_nuclear_gamma_yield,
    sources::GGEMSEnergyDistribution::BuildDiscreteLines(
      k_nuclear_gamma_energies_micro_eV, k_nuclear_gamma_line_yields));

  emissions.emplace_back(
    particles::GGEMSParticleType::Gamma, k_atomic_xray_yield,
    sources::GGEMSEnergyDistribution::BuildDiscreteLines(
      k_atomic_xray_energies_micro_eV, k_atomic_xray_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_776_52_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_776_52_keV_energies_micro_eV,
                           k_conversion_776_52_keV_line_yields));

  emissions.emplace_back(particles::GGEMSParticleType::Electron,
                         k_conversion_1474_88_keV_yield,
                         sources::GGEMSEnergyDistribution::BuildDiscreteLines(
                           k_conversion_1474_88_keV_energies_micro_eV,
                           k_conversion_1474_88_keV_line_yields));

  return {"Rb-82", k_half_life_seconds, std::move(emissions)};
}

